# SAME-SCENARIO\n\n\"\"\"\nfilter_metric_dimensions.py\nQuery metric data filtered by resource labels or dimensions (e.g., environment, instance_id).\n\"\"\"\n\nfrom observability_client import ManagedMetricsClient\n\ndef filter_metric_dimensions(metric_name: str, filter_params: dict, start_time: str, end_time: str) -> list:\n    \"\"\"Return datapoints matching the provided label/ dimension filters.\n\n    filter_params should be a dict such as {'environment': 'prod', 'instance_id': '123'}.\n    \"\"\"\n    client = ManagedMetricsClient()\n    return client.filter_metric_dimensions(metric_name, filter_params, start_time, end_time)
